import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath,pathToFileURL } from 'node:url';
import { Context } from '../lib/core.mjs';
import { handlers } from '../lib/javascript.mjs';
import { sha } from '../lib/javascript-model.mjs';
import { decodeSourceMap,originalPositions } from '../lib/javascript-sourcemaps.mjs';

const testRoot=path.dirname(fileURLToPath(import.meta.url));
async function fixture(t,files){const root=await fs.mkdtemp(path.join(testRoot,'javascript-parity-chain-'));t.after(async()=>{assert.ok(root.startsWith(`${testRoot}${path.sep}javascript-parity-chain-`));await fs.rm(root,{recursive:true,force:true});});for(const [name,value]of Object.entries(files)){const p=path.join(root,name);await fs.mkdir(path.dirname(p),{recursive:true});await fs.writeFile(p,value);}return root;}
const context=()=>{const c=new Context();c.handlers=handlers;return c;};
const flat=(name,content,mappings='AAAA',names=[])=>({version:3,sources:[name],sourcesContent:[content],names,mappings});
async function recover(c,root,name='root.map',out='output'){const evidence=await c.call('recover_javascript_sources',{path:path.join(root,name),output_directory:path.join(root,out),rewrite_level:'minimal'}),result=evidence.normalized_result,manifest=JSON.parse(await fs.readFile(result.manifest.path));return {evidence,result,manifest};}
const inline=map=>`data:application/json;base64,${Buffer.from(JSON.stringify(map)).toString('base64')}`;

test('recovery composes actual root/intermediate coordinates and retains both originals plus raw map receipts',async t=>{
  const original='export const original: number = 42;',intermediate='export const value = 42;\n//# sourceMappingURL=intermediate.map',rootMap=flat('intermediate.js',intermediate,'AAAAA',['bundledName']),child=flat('original.ts',original,'AAAU A'.replace(' ',''),['originalName']),root=await fixture(t,{'bundle.js':'export const value = 42;\n//# sourceMappingURL=root.map','root.map':JSON.stringify(rootMap),'intermediate.map':JSON.stringify(child)}),{result,manifest}=await recover(context(),root,'bundle.js');
  assert.equal(result.status,'complete');assert.equal(result.modules.length,3);assert.equal(manifest.source_map_composition.chain_map_count,1);assert.equal(manifest.source_map_composition.status,'complete-within-retained-maps');
  const map=decodeSourceMap(JSON.parse(await fs.readFile(manifest.source_map_composition.artifact.path))),position=originalPositions(map,0,0).mappings[0];assert.equal(path.basename(position.source.source),'original.ts');assert.equal(position.original.column,10);assert.equal(position.name,'originalName');assert.equal(position.original.contentPosition,'verified');
  assert.ok(result.modules.some(m=>m.provenance.original_sha256===sha(original)));assert.ok(result.modules.some(m=>m.provenance.original_sha256===sha(intermediate)));assert.equal(manifest.captured_chain_maps[0].artifact.sha256,sha(JSON.stringify(child)));assert.equal(await fs.readFile(manifest.captured_source_map.path,'utf8'),JSON.stringify(rootMap));assert.equal(result.runtime_equivalence,'unknown');
});
test('two-hop inline/indexed maps compose offsets without reading original files',async t=>{
  const original='export const leaf=42;',second='export const second=42;\n//# sourceMappingURL=last.map',child={version:3,sections:[{offset:{line:0,column:2},map:flat('second.js',second)}]},first=`export const first=42;\n//# sourceMappingURL=${inline(child)}`,rootMap={version:3,sections:[{offset:{line:1,column:4},map:flat('first.js',first,'AAAE')}]},last=flat('original.ts',original),root=await fixture(t,{'root.map':JSON.stringify(rootMap),'last.map':JSON.stringify(last),'original.ts':'throw new Error("must not be read")'}),c=context(),read=c.read.bind(c),reads=[];c.read=async(file,opts)=>{reads.push(path.resolve(file));return read(file,opts);};const {result,manifest}=await recover(c,root),decoded=decodeSourceMap(JSON.parse(await fs.readFile(manifest.source_map_composition.artifact.path))),position=originalPositions(decoded,1,4).mappings[0];
  assert.equal(result.modules.length,3);assert.equal(manifest.source_map_composition.chain_map_count,2);assert.equal(position.original.line,0);assert.equal(position.original.column,0);assert.equal(path.basename(position.source.source),'original.ts');assert.equal(manifest.source_map_composition.status,'complete-within-retained-maps');assert.ok(!reads.includes(path.join(root,'original.ts')));assert.equal(result.modules.find(m=>m.provenance.original_path==='original.ts').provenance.original_sha256,sha(original));
});
test('file-URL virtual source bases stay inside the input directory and composed file identities are valid URLs',async t=>{
  const root=await fixture(t,{'intermediate.js':'throw new Error("original file must not be read")','child.map':JSON.stringify(flat('original.ts','export const original=42;'))}),intermediate='export const value=42;\n//# sourceMappingURL=child.map';await fs.writeFile(path.join(root,'root.map'),JSON.stringify(flat(pathToFileURL(path.join(root,'intermediate.js')).href,intermediate)));const c=context(),read=c.read.bind(c),reads=[];c.read=async(file,opts)=>{reads.push(path.resolve(file));return read(file,opts);};const {result,manifest}=await recover(c,root),map=JSON.parse(await fs.readFile(manifest.source_map_composition.artifact.path));assert.equal(result.status,'complete');assert.ok(map.sources.every(source=>new URL(source).protocol==='file:'));assert.ok(!reads.includes(path.join(root,'intermediate.js')));assert.ok(reads.includes(path.join(root,'child.map')));const analysis=(await c.call('analyze_javascript_application',{input_path:root})).normalized_result;assert.equal(analysis.graph.nodes.find(n=>n.observations.some(o=>o.properties.path==='root.map')).observations[0].properties.source_map_composition.chain_map_count,1);
});
test('downstream duplicate mapping positions retain both original candidates and mark composition partial',async t=>{
  const intermediate='export const value=42;\n//# sourceMappingURL=child.map',child={version:3,sources:['left.ts','right.ts'],sourcesContent:['export const left=1;','export const right=2;'],names:[],mappings:'AAAA,ACAA'},root=await fixture(t,{'root.map':JSON.stringify(flat('intermediate.js',intermediate)),'child.map':JSON.stringify(child)}),{result,manifest}=await recover(context(),root),decoded=decodeSourceMap(JSON.parse(await fs.readFile(manifest.source_map_composition.artifact.path))),positions=originalPositions(decoded,0,0).mappings;
  assert.equal(result.status,'partial');assert.equal(positions.length,2);assert.deepEqual(new Set(positions.map(p=>path.basename(p.source.source))),new Set(['left.ts','right.ts']));assert.ok(result.warnings.some(w=>w.kind==='chain-ambiguous-intermediate-position'));assert.equal(result.modules.length,3);
});
test('missing intermediate text remains unknown and source names never authorize original-file discovery',async t=>{
  const root=await fixture(t,{'root.map':JSON.stringify(flat('intermediate.js',null)),'intermediate.js':'export const value=42;\n//# sourceMappingURL=child.map','child.map':JSON.stringify(flat('original.ts','export const original=42;'))}),c=context(),read=c.read.bind(c),reads=[];c.read=async(file,opts)=>{reads.push(path.resolve(file));return read(file,opts);};const {result,manifest}=await recover(c,root);
  assert.equal(result.status,'partial');assert.equal(result.modules.length,0);assert.equal(manifest.source_map_composition.chain_map_count,0);assert.equal(manifest.source_map_composition.artifact,null);assert.ok(result.warnings.some(w=>w.kind==='chain-missing-intermediate-text'));assert.deepEqual(new Set(reads),new Set([path.join(root,'root.map')]));
});
test('missing/remote downstream maps retain intermediate bytes without invented originals',async t=>{
  for(const [label,url]of [['missing','absent.map'],['remote','https://owned.invalid/child.map']]){const intermediate=`export const value=42;\n//# sourceMappingURL=${url}`,root=await fixture(t,{'root.map':JSON.stringify(flat('intermediate.js',intermediate))}),{result,manifest}=await recover(context(),root);assert.equal(result.status,'partial',label);assert.equal(result.modules.length,1);assert.equal(manifest.source_map_composition.chain_map_count,0);assert.ok(result.warnings.some(w=>w.kind==='chain-downstream-map-unavailable'));assert.equal(await fs.readFile(result.modules[0].artifact.path,'utf8'),intermediate);}
});
test('map-chain cycles stop with retained intermediate provenance rather than inventing a terminal source',async t=>{
  const intermediate='export const value=42;\n//# sourceMappingURL=root.map',root=await fixture(t,{'root.map':JSON.stringify(flat('intermediate.js',intermediate))}),{result,manifest}=await recover(context(),root);assert.equal(result.status,'partial');assert.equal(result.modules.length,1);assert.ok(result.warnings.some(w=>w.kind==='chain-map-chain-cycle'));assert.equal(manifest.source_map_composition.chain_map_count,0);assert.equal(manifest.source_map_composition.artifact,null);assert.equal(result.modules[0].provenance.original_sha256,sha(intermediate));
});
test('different retained bytes sharing one virtual source location prevent map association before child reads',async t=>{
  const a='export const a=1;\n//# sourceMappingURL=a.map',b='export const b=2;\n//# sourceMappingURL=b.map',root=await fixture(t,{'root.map':JSON.stringify({version:3,sources:['same.js','same.js'],sourcesContent:[a,b],names:[],mappings:'AAAA,ACAA'}),'a.map':JSON.stringify(flat('a.ts','export const a=1;')),'b.map':JSON.stringify(flat('b.ts','export const b=2;'))}),c=context(),read=c.read.bind(c),reads=[];c.read=async(file,opts)=>{reads.push(path.resolve(file));return read(file,opts);};const {result,manifest}=await recover(c,root);assert.equal(result.status,'partial');assert.equal(result.modules.length,2);assert.equal(manifest.source_map_composition.chain_map_count,0);assert.ok(result.warnings.some(w=>w.kind==='chain-ambiguous-source-association'));assert.deepEqual(new Set(reads),new Set([path.join(root,'root.map')]));
});
test('one downstream map path with conflicting captured bytes invalidates both branches and retains conflict receipts',async t=>{
  const a='export const a=1;\n//# sourceMappingURL=child.map',b='export const b=2;\n//# sourceMappingURL=child.map',first=flat('first.ts','export const first=1;'),second=flat('second.ts','export const second=2;'),root=await fixture(t,{'root.map':JSON.stringify({version:3,sources:['a.js','b.js'],sourcesContent:[a,b],names:[],mappings:'AAAA,ACAA'}),'child.map':JSON.stringify(first)}),c=context(),read=c.read.bind(c);let childReads=0;c.read=async(file,opts)=>path.resolve(file)===path.join(root,'child.map')&&++childReads===2?Buffer.from(JSON.stringify(second)):read(file,opts);const {result,manifest}=await recover(c,root),decoded=decodeSourceMap(JSON.parse(await fs.readFile(manifest.source_map_composition.artifact.path))),positions=originalPositions(decoded,0,0).mappings;assert.equal(result.status,'partial');assert.ok(result.warnings.some(w=>w.kind==='chain-conflicting-map-association'));assert.deepEqual(new Set(positions.map(p=>path.basename(p.source.source))),new Set(['a.js','b.js']));assert.deepEqual(new Set(manifest.captured_chain_maps.map(c=>c.artifact.sha256)),new Set([sha(JSON.stringify(first)),sha(JSON.stringify(second))]));
});
test('outside retained intermediate coordinates cannot become falsely verified terminal coordinates',async t=>{
  const intermediate='export const value=42;\n//# sourceMappingURL=child.map',root=await fixture(t,{'root.map':JSON.stringify(flat('intermediate.js',intermediate,'AAoGA')),'child.map':JSON.stringify(flat('original.ts','export const original=42;'))}),{result,manifest}=await recover(context(),root),decoded=decodeSourceMap(JSON.parse(await fs.readFile(manifest.source_map_composition.artifact.path)));assert.equal(result.status,'partial');assert.ok(result.warnings.some(w=>w.kind==='chain-original-position-outside-content'));assert.equal(path.basename(originalPositions(decoded,0,0).mappings[0].source.source),'intermediate.js');
});
test('analysis preserves the first mapping and a separately marked composed original coordinate',async t=>{
  const intermediate='export const value=42;\n//# sourceMappingURL=child.map',root=await fixture(t,{'bundle.js':'export function owned(){return 42;}\n//# sourceMappingURL=root.map','root.map':JSON.stringify(flat('intermediate.js',intermediate)),'child.map':JSON.stringify(flat('original.ts','export const original: number=42;','AAAQ'))}),r=(await context().call('analyze_javascript_application',{input_path:root})).normalized_result,fn=r.semantic_graph.nodes.find(n=>n.kind==='function'&&n.label==='owned');assert.equal(r.statistics.parse_failures,0);assert.equal(fn.properties.source_map_locations[0].source,'intermediate.js');assert.equal(fn.properties.composed_source_map_locations[0].source,'original.ts');assert.equal(fn.properties.composed_source_map_locations[0].original.column,8);assert.equal(fn.properties.composed_source_map_locations[0].composition_complete,true);assert.equal(r.graph.coverage.status,'complete');
});
test('chained-map cancellation propagates before publishing any evidence',async t=>{
  const intermediate='export const value=42;\n//# sourceMappingURL=child.map',root=await fixture(t,{'root.map':JSON.stringify(flat('intermediate.js',intermediate)),'child.map':JSON.stringify(flat('original.ts','export const original=42;'))}),controller=new AbortController(),c=new Context({signal:controller.signal});c.handlers=handlers;const read=c.read.bind(c);c.read=async(file,opts)=>{const bytes=await read(file,opts);if(path.resolve(file)===path.join(root,'child.map'))controller.abort();return bytes;};await assert.rejects(()=>recover(c,root),/cancel|abort/i);assert.equal(c.ledger.size,0);assert.equal(c.history.length,0);
});
test('sparse huge generated offsets reach an encoded-output capacity boundary without allocating enormous line arrays',async t=>{
  const root=await fixture(t,{'root.map':JSON.stringify({version:3,sections:[{offset:{line:20000000,column:0},map:flat('original.ts','export const original=42;')}]})}),c=context();await assert.rejects(()=>recover(c,root),/encoded line budget/);assert.equal(c.ledger.size,0);
});
test('composed JSON exceeding the existing per-file limit fails before publication even when each captured map fits',async t=>{
  const a='export const a=1;\n//# sourceMappingURL=a.map',b='export const b=2;\n//# sourceMappingURL=b.map',root=await fixture(t,{'root.map':JSON.stringify({version:3,sources:['a.js','b.js'],sourcesContent:[a,b],names:[],mappings:'AAAA,ACAA'}),'a.map':JSON.stringify(flat('a.ts',`/* owned a ${'x'.repeat(9*1024*1024)} */`)),'b.map':JSON.stringify(flat('b.ts',`/* owned b ${'y'.repeat(9*1024*1024)} */`))}),c=context();await assert.rejects(()=>recover(c,root),/file-byte budget/);assert.equal(c.ledger.size,0);assert.equal(c.history.length,0);
});
